{
  "what_happened": "A PowerShell process compressed sensitive files (design_docs.zip) on ENG-17, then performed a DNS TXT burst with high-entropy subdomains to sync-cloud.example, exfiltrating approximately 48 MB of data, far exceeding normal TXT traffic. This indicates data exfiltration via DNS tunneling.",
  "evidence": [
    {
      "id": "E3",
      "observation": "PowerShell compressed archive design_docs.zip before DNS burst",
      "relevance": "Indicates staging of sensitive data for exfiltration"
    },
    {
      "id": "E1",
      "observation": "220 TXT queries with high-entropy subdomains to sync-cloud.example",
      "relevance": "High volume and entropy suggest encoded data in DNS queries, a classic DNS tunneling pattern"
    },
    {
      "id": "E2",
      "observation": "48 MB transferred via TXT while baseline is below 20 KB",
      "relevance": "Volume anomaly confirms exfiltration of large data"
    }
  ],
  "attack_techniques": [
    {
      "technique_id": "T1560.001",
      "technique_name": "Archive Collected Data",
      "procedure": "PowerShell compresses files into design_docs.zip"
    },
    {
      "technique_id": "T1048.003",
      "technique_name": "Exfiltration Over Alternative Protocol",
      "procedure": "Data encoded in DNS TXT queries to sync-cloud.example"
    },
    {
      "technique_id": "T1071.004",
      "technique_name": "Application Layer Protocol: DNS",
      "procedure": "Using DNS TXT for covert data transfer"
    }
  ],
  "containment_steps": [
    "Block outbound DNS queries to sync-cloud.example at the firewall and DNS sinkhole the domain.",
    "Isolate ENG-17 from the network to prevent further data leakage.",
    "Terminate the PowerShell process if still running and disable the user account associated with ENG-17 if compromised.",
    "Review DNS logs for other hosts querying sync-cloud.example to identify potential lateral movement or additional affected systems.",
    "Preserve forensic evidence: collect memory dump, process list, network connections, and the design_docs.zip file for investigation."
  ]
}

{
  "summary": "The svc_backup account was targeted in a brute-force attack from IP 10.24.7.19, which succeeded at 08:14:41. The attacker then used RDP to move laterally to FIN-WS22 at 08:16:09. A backup agent heartbeat at 08:16:12 indicates normal system activity, but the successful logon and RDP session suggest unauthorized access.",
  "evidence": [
    "E1: 42 failed logons for svc_backup from 10.24.7.19 at 08:14:03",
    "E2: successful logon for svc_backup from 10.24.7.19 at 08:14:41",
    "E3: svc_backup opened RDP session to FIN-WS22 at 08:16:09"
  ],
  "attack_chain": [
    {
      "tactic": "Initial Access",
      "technique": "Valid Accounts",
      "id": "T1078",
      "detail": "The attacker used valid credentials for svc_backup after brute-forcing the password."
    },
    {
      "tactic": "Lateral Movement",
      "technique": "Remote Desktop Protocol",
      "id": "T1021.001",
      "detail": "The attacker used RDP from svc_backup to access FIN-WS22."
    }
  ],
  "containment": {
    "immediate": [
      "1. Disable the svc_backup account immediately.",
      "2. Block IP 10.24.7.19 at the firewall and any other network boundaries.",
      "3. Terminate any active RDP sessions from svc_backup, especially to FIN-WS22."
    ],
    "short_term": [
      "4. Reset the password for svc_backup and all accounts that share similar credentials.",
      "5. Isolate FIN-WS22 from the network to prevent further lateral movement.",
      "6. Review authentication logs for other successful logons from 10.24.7.19."
    ],
    "long_term": [
      "7. Implement account lockout policies and multi-factor authentication for privileged accounts.",
      "8. Enforce least privilege for service accounts and restrict RDP usage.",
      "9. Conduct a full investigation to assess data compromise and impact."
    ]
  }
}

{
  "summary": "The user approved a malicious OAuth application, which then accessed a large volume of emails via the Graph API. The attacker used a refresh token after a password reset to maintain persistence.",
  "evidence": [
    "E1: Approval of unverified OAuth app 'MailSync' with Mail.Read scope at 09:02:11.",
    "E2: MailSync read 1840 messages via Graph API from a new ASN at 09:04:20.",
    "E3: Refresh token used after user password reset at 09:05:01."
  ],
  "attack_mapping": {
    "Initial Access": "T1566.002 - Phishing: Spearphishing Link (user tricked into approving OAuth app)",
    "Persistence": "T1098.001 - Account Manipulation: Additional Cloud Credentials (OAuth app with refresh token)",
    "Collection": "T1114.002 - Email Collection: Remote Email Collection (Graph API read emails)"
  },
  "containment": [
    "Disable the OAuth application 'MailSync' and revoke its consent.",
    "Revoke all refresh tokens for the affected user and require re-authentication.",
    "Force a password reset and enable MFA for the user.",
    "Audit other OAuth grants and remove any unknown or unverified apps.",
    "Alert the user and review mailbox access logs for further suspicious activity."
  ]
}

{
  "what_happened": "The workstation's user account likely was compromised and used to request numerous service tickets (Kerberoasting) to obtain password hashes for offline cracking. The attacker then used the cracked credentials of svc_sql to log on interactively and access an administrative share on DB-02.",
  "evidence": [
    {
      "id": "E1",
      "significance": "73 service tickets in two minutes indicates abnormal enumeration of SPNs, typical of Kerberoasting."
    },
    {
      "id": "E2",
      "significance": "Interactive logon with svc_sql from a workstation is anomalous because service accounts typically do not have interactive logon rights."
    },
    {
      "id": "E3",
      "significance": "Connection to admin share (C$) from a non-admin source suggests lateral movement or data access."
    }
  ],
  "attack_chain": [
    {
      "technique_id": "T1558.003",
      "technique": "Kerberoasting"
    },
    {
      "technique_id": "T1078",
      "technique": "Valid Accounts"
    },
    {
      "technique_id": "T1021.002",
      "technique": "SMB/Windows Admin Shares"
    }
  ],
  "containment_steps": [
    "Disable the svc_sql account and reset its password immediately.",
    "Isolate the workstation from the network to prevent further malicious activity.",
    "Revoke any active sessions and tokens associated with svc_sql.",
    "Restrict interactive logon rights for service accounts and enforce strong password policies.",
    "Investigate the workstation for other indicators of compromise and perform memory/disk forensics.",
    "Monitor for other accounts requesting service tickets and audit for similar patterns."
  ]
}

{
  "summary": "A signed vendor updater executed msiexec at 18:00:02 on a pilot-ring machine, following an approved change ticket and matching the vendor's manifest hash, indicating a legitimate software update.",
  "evidence": [
    {
      "id": "E1",
      "source": "edr",
      "timestamp": "18:00:02",
      "event": "signed vendor updater spawned msiexec",
      "relevance": "Shows the execution of the update process."
    },
    {
      "id": "E2",
      "source": "change",
      "timestamp": "17:55:00",
      "event": "CHG-9012 authorizes vendor update on pilot ring",
      "relevance": "Confirms the update was pre-approved and scoped to the pilot ring."
    },
    {
      "id": "E3",
      "source": "hash",
      "timestamp": "18:00:05",
      "event": "binary hash matches vendor release manifest",
      "relevance": "Validates the integrity of the executed binary."
    }
  ],
  "att&ck": [
    {
      "technique_id": "T1072",
      "technique_name": "Software Deployment Tools",
      "tactic": "Execution",
      "mapping_justification": "The vendor updater is a legitimate software deployment tool used to install updates."
    },
    {
      "technique_id": "T1218",
      "technique_name": "System Binary Proxy Execution",
      "tactic": "Defense Evasion",
      "mapping_justification": "msiexec is a system binary commonly abused but here used legitimately to run the update."
    }
  ],
  "containment": [
    "Verify the update is in the approved change scope (CHG-9012) and the host is in the pilot ring.",
    "Confirm the msiexec process arguments correspond to the vendor's update package path and parameters.",
    "Check the vendor's release notes or change ticket for expected post-update behavior or known side effects.",
    "Review EDR logs for any subsequent suspicious child processes or network connections from the msiexec process.",
    "If no anomalies are found, allow the update to complete and monitor for stability or errors.",
    "If suspicious activity is detected, isolate the host and revoke the updater's signing certificate from the trust store after consulting the vendor."
  ]
}

{
  "summary": "An initial compromise was executed via a macro-enabled Word document that spawned a PowerShell process with an encoded command, establishing persistence through a registry Run key, and beaconing to a newly registered domain for command-and-control.",
  "evidence": [
    {
      "id": "E1",
      "source": "EDR",
      "timestamp": "13:20:02",
      "observation": "WINWORD.exe spawned PowerShell.exe with an encoded command. This indicates a macro or embedded object executed a PowerShell payload."
    },
    {
      "id": "E2",
      "source": "Registry",
      "timestamp": "13:20:15",
      "observation": "A new HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run value named 'UpdateCheck' was added, pointing to a PowerShell payload. This ensures persistence for the malicious payload."
    },
    {
      "id": "E3",
      "source": "Network",
      "timestamp": "13:20:19",
      "observation": "PowerShell process established a connection to the newly registered domain 'cdn-check.example', indicating command-and-control (C2) communication."
    }
  ],
  "attack_chain": {
    "initial_access": "T1566.001 Spearphishing Attachment (macro-enabled Word document)",
    "execution": "T1059.001 PowerShell (encoded command from WINWORD)",
    "persistence": "T1547.001 Registry Run Keys / Startup Folder (HKCU Run value UpdateCheck)",
    "command_and_control": "T1071.001 Application Layer Protocol: Web Protocols (HTTP/HTTPS to cdn-check.example)",
    "defense_evasion": "T1027.001 Encrypted/Encoded File or Command (encoded PowerShell)"
  },
  "containment": [
    "1. Isolate the affected host from the network immediately.",
    "2. Terminate the malicious PowerShell process and remove the registry Run key 'UpdateCheck'.",
    "3. Delete the macro-enabled Word document and any dropped payloads from the host.",
    "4. Block the domain 'cdn-check.example' at the firewall/proxy.",
    "5. Collect a full memory image and disk forensic artifacts for further analysis.",
    "6. Reset credentials of any accounts used on the host.",
    "7. Scan the network for other hosts communicating with the same domain."
  ]
}

